def check_condition(x):
    n = len(x)
    for i in range(1, n - 1):
        if x[i+1]*x[i-1] + x[i+1] + x[i-1] != x[i]**2:
            return False
    return True

def search_n(max_val, n):
    import itertools
    for x in itertools.product(range(1, max_val + 1), repeat=n):
        if check_condition(x):
            return x
    return None

for n in range(3, 7):
    res = search_n(50, n)
    print(f"n={n}: {res}")

def find_sequence(start_x1, start_x2, n_max):
    x = [start_x1, start_x2]
    for i in range(2, n_max):
        # (x[i-2]+1)(x[i]+1) = x[i-1]**2 + 1
        # x[i] = (x[i-1]**2 + 1) / (x[i-2] + 1) - 1
        numerator = x[i-1]**2 + 1
        denominator = x[i-2] + 1
        if numerator % denominator == 0:
            val = numerator // denominator - 1
            if val > 0:
                x.append(val)
            else:
                break
        else:
            break
    return x

