def search_n5_efficient(limit):
    for y1 in range(2, limit):
        # Optimization: only y1 that can divide z^2+1
        # Prime factors must be 2 or 4k+1
        # Let's just check the condition (y2-1)^2 + 1 = 0 mod y1
        # instead of the prime factor check.
        for y2 in range(2, limit):
            if (y2-1)**2 + 1 == 0: # this is not possible
                pass
            if ((y2-1)**2 + 1) % y1 == 0:
                y = get_y_seq(y1, y2, 5)
                if len(y) >= 5:
                    return y
    return None

